using UnityEngine;

namespace GoodCopBadCop.FilmStudio
{
    /// <summary>
    /// Pre-validated camera position inside a <see cref="StudioSet"/> (clear line of sight to a mark at head height).
    /// Shots reference it with camera.spotId; the lens is then fitted to the requested framing from this distance.
    /// Generated by StudioSetAnalyzer; hand-placed spots work too (add the component to any transform under the set).
    /// </summary>
    public class StudioCameraSpot : MonoBehaviour
    {
        public string spotId;
        [TextArea(1, 3)] public string description;
        [Tooltip("Mark this spot was validated against (informational).")]
        public string markId;
        [Tooltip("The sight line passes through glass: runtime deocclusion is disabled for shots from this spot.")]
        public bool throughGlass;

        private void OnDrawGizmos()
        {
            Gizmos.color = throughGlass ? new Color(0.3f, 0.8f, 1f, 0.9f) : new Color(1f, 0.4f, 0.9f, 0.9f);
            Vector3 p = transform.position;
            Gizmos.DrawWireCube(p, new Vector3(0.18f, 0.12f, 0.12f));
            Gizmos.DrawLine(p, p + transform.forward * 0.4f);
        }
    }
}
